```go
package lesson

import (
	"fmt"
	"strconv"
)

func ParsePort(value string) (int, error) {
	port, err := strconv.Atoi(value)
	if err != nil || port < 1 || port > 65535 {
		return 0, fmt.Errorf("invalid port %q", value)
	}
	return port, nil
}
```

**port_test.go**

```go
package lesson

import "testing"

func TestParsePort(t *testing.T) {
	t.Run("valid", func(t *testing.T) {
		got, err := ParsePort("8080")
		if err != nil {
			t.Fatal(err)
		}
		if got != 8080 {
			t.Errorf("got %d; want 8080", got)
		}
	})
	t.Run("out of range", func(t *testing.T) {
		if _, err := ParsePort("70000"); err == nil {
			t.Error("expected an error")
		}
	})
}
```

**Run it**

```bash
go test -v ./...
```

The subtest names turn two branches into separate results while the parent still describes the shared behaviour under test.

**file_test.go**

```go
package lesson

import (
	"io"
	"os"
	"testing"
)

func testFile(t *testing.T, value string) *os.File {
	t.Helper()
	file, err := os.CreateTemp(t.TempDir(), "value-*")
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = file.Close() })
	if _, err := file.WriteString(value); err != nil {
		t.Fatal(err)
	}
	if _, err := file.Seek(0, io.SeekStart); err != nil {
		t.Fatal(err)
	}
	return file
}

func TestFileContents(t *testing.T) {
	file := testFile(t, "ready")
	got, err := io.ReadAll(file)
	if err != nil {
		t.Fatal(err)
	}
	if string(got) != "ready" {
		t.Fatalf("got %q; want ready", got)
	}
}
```

**Run it**

```bash
go test ./...
```

The helper owns acquisition and fallback release; the test sees a ready-to-use file and receives failures at its call site.

**greeting.go**

```go
package lesson

func GreetingFrom(lookup func(string) (string, bool)) string {
	name, ok := lookup("APP_NAME")
	if !ok || name == "" {
		return "hello, app"
	}
	return "hello, " + name
}
```

**greeting_test.go**

```go
package lesson

import "testing"

func TestGreetingFrom(t *testing.T) {
	cases := map[string]map[string]string{
		"configured": {"APP_NAME": "api"},
		"missing":    {},
	}
	for name, values := range cases {
		name, values := name, values
		t.Run(name, func(t *testing.T) {
			t.Parallel()
			lookup := func(key string) (string, bool) {
				value, ok := values[key]
				return value, ok
			}
			got := GreetingFrom(lookup)
			if got == "" {
				t.Error("greeting must not be empty")
			}
		})
	}
}
```

**Run it**

```bash
go test -race ./...
```

Every subtest owns its lookup data. No process environment changes, restoration races, or special execution order are required.
